def compute(vars):
    acquisition_related_cost = vars["v1"]
    total_cost = vars["v2"]
    if total_cost == 0:
        return None
    proportion = acquisition_related_cost / total_cost
    return {
        "value": proportion,
        "trace": {
            "acquisition_related_cost": acquisition_related_cost,
            "total_cost": total_cost,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
